$content = Get-Content index.html -Raw; Write-Host "Scripts Open: " ([regex]::Matches($content, "<script\b[^>]*>").Count); Write-Host "Scripts Close: " ([regex]::Matches($content, "</script>").Count); $block = (Get-Content index.html)[5251..5356] -join "`n"; Write-Host "Braces Open: " ([regex]::Matches($block, "\{").Count); Write-Host "Braces Close: " ([regex]::Matches($block, "\}").Count); Write-Host "Parens Open: " ([regex]::Matches($block, "\(").Count); Write-Host "Parens Close: " ([regex]::Matches($block, "\)").Count); Write-Host "Backticks: " ([regex]::Matches($block, "``").Count);
